/**
 * Correlation IDs (architecture.md §22): one non-sensitive random ID per API request, carried into
 * structured logs and background job payloads so one incident can be traced across Vercel,
 * Supabase and Trigger.dev. Generated by Madeora's server only; an ID sent by a client is never
 * trusted, so nobody can inject text into log lines or tie their requests to someone else's.
 */

/** The request header that carries the ID from the proxy to route handlers, and back out. */
export const CORRELATION_HEADER = "x-correlation-id";

const UUID_V4 = /^[0-9a-f]{8}-[0-9a-f]{4}-4[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/;

/** A fresh correlation ID: a random UUID v4 (Web Crypto, so it works in Node and edge runtimes). */
export function newCorrelationId(): string {
  return globalThis.crypto.randomUUID();
}

/** Whether `value` has the exact shape Madeora generates (lower-case UUID v4). */
export function isCorrelationId(value: unknown): value is string {
  return typeof value === "string" && UUID_V4.test(value);
}
